import{Tt as e,at as t,et as n,rt as r,t as i}from"./chunks/framework.BrsnRMCg.js";var a=JSON.parse(`{"title":"Authorization","description":"","frontmatter":{"title":"Authorization","order":3},"headers":[],"relativePath":"services/authorization/index.md","filePath":"services/authorization/index.md"}`),o={name:`services/authorization/index.md`};function s(i,a,o,s,c,l){return e(),r(`div`,{"data-pagefind-body":!0,"data-pagefind-meta":`date:1795284828000`},[...a[0]||=[t(`<h1 id="authorization-service" tabindex="-1">Authorization Service <a class="header-anchor" href="#authorization-service" aria-label="Permalink to “Authorization Service”">​</a></h1><p>Go service that answers permission checks (Casbin policies, workspace memberships and roles) over gRPC for the other services.</p><ul><li><a href="./domain.html">Domain</a>: class diagrams</li><li><a href="./data.html">Data</a>: database schema</li><li><a href="./flows.html">Flows</a>: permission checks and membership changes</li></ul><h2 id="use-cases" tabindex="-1">Use cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to “Use cases”">​</a></h2><p>Authorization exposes an internal gRPC API; callers supply the user and workspace IDs. It stores workspace-scoped role assignments, not workspace metadata or individual note ACLs. The calling service is responsible for identifying the user and enforcing the result of a check.</p><table tabindex="0"><thead><tr><th>Use case</th><th>RPC</th><th>Behavior</th></tr></thead><tbody><tr><td>Create initial membership</td><td><code>CreateWorkspaceWithOwner</code></td><td>Adds the supplied owner-to-workspace role assignment; a duplicate assignment is an error.</td></tr><tr><td>List a user&#39;s workspaces</td><td><code>GetUserWorkspaces</code></td><td>Returns workspace IDs and roles from that user&#39;s grouping policies.</td></tr><tr><td>List members</td><td><code>GetWorkspaceMembers</code></td><td>Requires workspace read permission and returns user IDs and roles.</td></tr><tr><td>Replace members</td><td><code>UpdateWorkspaceMembers</code></td><td>Requires workspace edit permission and replaces the complete membership list, generating events for additions, role changes and removals.</td></tr><tr><td>Leave a workspace</td><td><code>LeaveWorkspace</code></td><td>Removes the caller&#39;s membership, except when the caller is the only owner.</td></tr><tr><td>Delete authorization data</td><td><code>DeleteWorkspace</code></td><td>Requires workspace delete permission and removes all membership policies for that workspace, not the workspace itself.</td></tr><tr><td>Check access</td><td><code>HasWorkspacePermission</code>, <code>HasWorkspaceItemPermission</code></td><td>Return a boolean for a workspace action or a workspace-wide item action.</td></tr><tr><td>Get item capabilities</td><td><code>GetUserWorkspaceItemPermissions</code></td><td>Requires workspace read permission, then returns item read, write and delete decisions.</td></tr></tbody></table><p>The replacement request must contain at least one member. Unlike <code>LeaveWorkspace</code>, its handler does not check that an owner remains. These operations do not create or delete the corresponding workspace in another service.</p><h2 id="roles-and-permissions" tabindex="-1">Roles and permissions <a class="header-anchor" href="#roles-and-permissions" aria-label="Permalink to “Roles and permissions”">​</a></h2><p>The seeded policy grants the following actions:</p><table tabindex="0"><thead><tr><th>Role</th><th>Workspace</th><th>Workspace items</th></tr></thead><tbody><tr><td>Owner</td><td>read, edit, delete, billing read, billing manage</td><td>read, write, delete</td></tr><tr><td>Editor</td><td>read, billing read</td><td>read, write, delete</td></tr><tr><td>Viewer</td><td>read, billing read</td><td>read</td></tr></tbody></table><p>Casbin&#39;s <code>g</code> policies associate a user with a role in a workspace. Static <code>p</code> policies grant actions to roles; <code>g2</code> maps note and folder objects to the <code>workspace_item</code> class. The item-check RPCs check the class for the whole workspace, not a particular item ID.</p><p>The static policy is seeded separately with <code>just seed-authorization</code>; development memberships are loaded separately with <code>just fixtures-authorization</code>. At startup, policy drift is logged and fails the policy health check; the running enforcer does not watch the database, so restart it after correcting the seed.</p><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to “Architecture”">​</a></h2>`,13),n(`figure`,{class:`vpd-diagram vpd-diagram--d2`,onclick:`
        const figure = this;
        const isFullscreen = figure.classList.contains('vpd-diagram--fullscreen');

        document.querySelectorAll('.vpd-diagram').forEach(diagram => {
          diagram.classList.remove('vpd-diagram--fullscreen');
        });

        if (!isFullscreen) {
          figure.classList.add('vpd-diagram--fullscreen');
        }
      `},[n(`img`,{src:`/notopia/pr/428/diagrams/d2-architecture-authorization-diagram-506395c9a81c339a1297b95ff77299d1.svg`,alt:`d2 Diagram`,class:`vpd-diagram-image`})],-1)]])}var c=i(o,[[`render`,s]]);export{a as __pageData,c as default};